-- Seed: one live work (N°03) with its 60×80 intermediate guide, palettes, shopping list and an A3 edition.
-- Images are mock artworks from public/mock (same as the canvas).
select g.id, 1, jsonb_build_object('layers', (select jsonb_agg(jsonb_build_object('position', l.position, 'name', l.name, 'brush', l.brush, 'plate', l.plate, 'tip', l.tip, 'dry_seconds', l.dry_seconds, 'diagram', l.diagram,
  'steps', (select jsonb_agg(jsonb_build_object('position', s.position, 'text', s.text) order by s.position) from guide_steps s where s.layer_id = l.id)) order by l.position) from guide_layers l where l.guide_id = g.id))
from guides g where g.id = '00000000-0000-0000-0000-0000000000a3';
